// Generated bytes only; never access a saved wallet profile.
import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, writeFile, readFile, readdir, rm, stat, symlink, open } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { gzipSync, gunzipSync } from 'node:zlib';
import { readEvidenceFile, writeEvidenceJson, compactEvidenceFile, expandEvidenceFile,
  COMPACT_EVIDENCE_MAX_BYTES } from './evidence-storage.mjs';

async function fixture(t) {
  const root = await mkdtemp(join(tmpdir(), 'godl-evidence-storage-'));
  t.after(() => rm(root, { recursive: true, force: true }));
  return { root, path: join(root, 'response-000001.json') };
}

test('new evidence compresses exact serialized bytes with private permissions and no temporary residue', async t => {
  const f = await fixture(t), value = { raw: 'synthetic'.repeat(1000), exact: '9007199254740993' };
  assert.equal(await writeEvidenceJson(f.path, value), `${f.path}.gz`);
  const expected = Buffer.from(JSON.stringify(value, null, 2) + '\n');
  assert.deepEqual(gunzipSync(await readFile(`${f.path}.gz`)), expected);
  assert.deepEqual(await readEvidenceFile(f.path), expected);
  assert.deepEqual(await readEvidenceFile(`${f.path}.gz`), expected);
  assert.equal((await stat(`${f.path}.gz`)).mode & 0o777, 0o600);
  assert.deepEqual(await readdir(f.root), ['response-000001.json.gz']);
  const small = join(f.root, 'small.json');
  assert.equal(await writeEvidenceJson(small, 1), small);
  assert.equal(await readFile(small, 'utf8'), '1\n');
});

test('plaintext wins and only missing plaintext falls back, while gzip corruption fails closed', async t => {
  const f = await fixture(t);
  await writeFile(`${f.path}.gz`, gzipSync('compressed'));
  await writeFile(f.path, 'plain');
  assert.equal((await readEvidenceFile(f.path)).toString(), 'plain');
  await rm(f.path);
  assert.equal((await readEvidenceFile(f.path)).toString(), 'compressed');
  await writeFile(`${f.path}.gz`, 'broken gzip');
  await assert.rejects(readEvidenceFile(f.path));
  await writeFile(f.path, '{invalid json');
  await assert.rejects(async () => JSON.parse((await readEvidenceFile(f.path)).toString()), SyntaxError);
});

test('evidence writer reuses matching forms and preserves conflicting, corrupt and symlink destinations', async t => {
  const f = await fixture(t), value = { raw: 'synthetic'.repeat(1000) };
  const bytes = Buffer.from(JSON.stringify(value, null, 2) + '\n');
  await writeFile(f.path, bytes, { mode: 0o640 });
  assert.equal(await writeEvidenceJson(f.path, value), f.path);
  assert.equal((await stat(f.path)).mode & 0o777, 0o640);
  await assert.rejects(writeEvidenceJson(f.path, { raw: 'changed' }), /Conflicting/);
  assert.deepEqual(await readFile(f.path), bytes);
  await writeFile(`${f.path}.gz`, gzipSync(bytes));
  assert.equal(await writeEvidenceJson(f.path, value), f.path);
  await rm(f.path);
  const originalCompressed = await readFile(`${f.path}.gz`);
  assert.equal(await writeEvidenceJson(f.path, value), `${f.path}.gz`);
  assert.deepEqual(await readFile(`${f.path}.gz`), originalCompressed);
  await assert.rejects(writeEvidenceJson(f.path, { raw: 'changed' }), /Conflicting/);
  assert.deepEqual(await readFile(`${f.path}.gz`), originalCompressed);
  await writeFile(`${f.path}.gz`, 'corrupt gzip');
  await assert.rejects(writeEvidenceJson(f.path, value));
  assert.equal(await readFile(`${f.path}.gz`, 'utf8'), 'corrupt gzip');
  await writeFile(f.path, bytes);
  await assert.rejects(writeEvidenceJson(f.path, value));
  assert.deepEqual(await readFile(f.path), bytes);
  await rm(f.path); await rm(`${f.path}.gz`);
  const target = join(f.root, 'target'); await writeFile(target, bytes);
  for (const path of [f.path, `${f.path}.gz`]) {
    await symlink(target, path);
    await assert.rejects(writeEvidenceJson(f.path, value));
    assert.deepEqual(await readFile(target), bytes);
    await rm(path);
  }
});

test('reads reject symlinks, directories, compressed bombs and oversized plaintext', async t => {
  const f = await fixture(t), target = join(f.root, 'target');
  await writeFile(target, 'private synthetic');
  await writeFile(`${f.path}.gz`, gzipSync('fallback'));
  await symlink(target, f.path);
  await assert.rejects(readEvidenceFile(f.path));
  await assert.rejects(readEvidenceFile(f.root));
  await rm(f.path); await rm(`${f.path}.gz`);
  await symlink(target, `${f.path}.gz`);
  await assert.rejects(readEvidenceFile(f.path));
  await rm(`${f.path}.gz`);
  await writeFile(f.path, 'x'.repeat(101));
  await assert.rejects(readEvidenceFile(f.path, { maxBytes: 100 }), /byte limit/);
  await rm(f.path); await writeFile(`${f.path}.gz`, gzipSync('x'.repeat(101)));
  await assert.rejects(readEvidenceFile(f.path, { maxBytes: 100 }));
});

test('offline compaction and expansion preserve every original byte, modes and idempotent restart', async t => {
  const f = await fixture(t);
  const original = Buffer.from(' { "unsafe": 9007199254740993,\r\n"raw":"' + 'x'.repeat(10000) + '" }\t\n');
  await writeFile(f.path, original, { mode: 0o640 });
  assert.equal((await compactEvidenceFile(f.path)).status, 'compacted');
  await assert.rejects(readFile(f.path), { code: 'ENOENT' });
  assert.deepEqual(await readEvidenceFile(f.path), original);
  assert.equal((await compactEvidenceFile(f.path)).status, 'compacted');
  assert.equal((await expandEvidenceFile(`${f.path}.gz`)).status, 'expanded');
  assert.deepEqual(await readFile(f.path), original);
  assert.equal((await stat(f.path)).mode & 0o777, 0o600);
  assert.equal((await expandEvidenceFile(f.path)).status, 'expanded');
  assert.deepEqual(await readdir(f.root), ['response-000001.json']);
});

test('interrupted matching forms resume safely; conflicting forms and corrupt gzip preserve both', async t => {
  const f = await fixture(t), bytes = Buffer.from('synthetic '.repeat(1000));
  for (const operation of [compactEvidenceFile, expandEvidenceFile]) {
    await writeFile(f.path, bytes); await writeFile(`${f.path}.gz`, gzipSync(bytes));
    await operation(f.path);
    assert.deepEqual(await readEvidenceFile(f.path), bytes);
    await rm(f.path, { force: true }); await rm(`${f.path}.gz`, { force: true });
    for (const compressed of [gzipSync('conflict'), Buffer.from('corrupt')]) {
      await writeFile(f.path, bytes); await writeFile(`${f.path}.gz`, compressed);
      await assert.rejects(operation(f.path));
      assert.deepEqual(await readFile(f.path), bytes);
      assert.deepEqual(await readFile(`${f.path}.gz`), compressed);
    }
  }
});

test('offline compaction skips oversized input without hiding or altering it; small incompressible data stays plain', async t => {
  const f = await fixture(t), file = await open(f.path, 'wx', 0o600);
  await file.truncate(COMPACT_EVIDENCE_MAX_BYTES + 1); await file.close();
  const before = await stat(f.path);
  assert.deepEqual(await compactEvidenceFile(f.path), { status: 'skipped', reason: 'oversized', path: f.path });
  assert.equal((await stat(f.path)).size, before.size);
  assert.equal((await stat(f.path)).mtimeMs, before.mtimeMs);
  assert.deepEqual(await readdir(f.root), ['response-000001.json']);
  await writeFile(f.path, '1');
  assert.equal((await compactEvidenceFile(f.path)).reason, 'not-beneficial');
});

test('cache-size reader supports valid evidence beyond the claim inspector limit', async t => {
  const f = await fixture(t), bytes = Buffer.from(' '.repeat(9 * 1024 * 1024));
  await writeFile(`${f.path}.gz`, gzipSync(bytes));
  assert.deepEqual(await readEvidenceFile(f.path), bytes);
  await assert.rejects(readEvidenceFile(f.path, { maxBytes: 8 * 1024 * 1024 }));
});

test('oversized gzip remains intact when offline expansion reaches its decompressed limit', async t => {
  const f = await fixture(t), bytes = gzipSync(Buffer.alloc(COMPACT_EVIDENCE_MAX_BYTES + 1));
  await writeFile(`${f.path}.gz`, bytes);
  assert.deepEqual(await expandEvidenceFile(f.path), { status: 'skipped', reason: 'oversized', path: `${f.path}.gz` });
  assert.deepEqual(await readFile(`${f.path}.gz`), bytes);
  await assert.rejects(readFile(f.path), { code: 'ENOENT' });
  assert.deepEqual(await compactEvidenceFile(f.path), { status: 'skipped', reason: 'oversized', path: `${f.path}.gz` });
});
